// The line a person reads when checking on this in n8n.
// $input, not $json: this Code node runs once for all items.
const r = $input.first().json || {};
if (!String($env.CRON_SECRET || '').trim()) {
  return [{ json: { summary: 'CRON_SECRET is not set on the box, so the app refuses this call. Add it to n8n/docker/.env (the same value as on Vercel) and restart n8n.' } }];
}
if (r.ok !== true) {
  return [{ json: { summary: `The app refused or failed (${r.statusCode || r.error || 'no answer'}). Check CRON_SECRET matches Vercel's.`, ...r } }];
}
if (!r.window) {
  return [{ json: { summary: `Outside sending hours. Next window: ${r.nextWindow || 'unknown'}.` } }];
}
const lines = (r.workspaces || []).flatMap(w => (w.mailboxes || []).map(m => `${m.mailbox}: ${m.reason}`));
return [{ json: { summary: `Sent ${r.sent || 0}, skipped ${r.skipped || 0}, failed ${r.failed || 0}.`, mailboxes: lines, ...r } }];
